$ErrorActionPreference = "Stop"

$inputPath = Join-Path $PSScriptRoot "..\data\input"
New-Item -ItemType Directory -Force -Path $inputPath | Out-Null

$samples = @{
    "habilitacao-ficticia-2026-001.pdf" = ""
    "habilitacao-ficticia-2025-002.pdf" = ""
}

foreach ($sample in $samples.GetEnumerator()) {
    $path = Join-Path $inputPath $sample.Key
    [IO.File]::WriteAllBytes($path, [Convert]::FromBase64String($sample.Value))
}

Write-Host "2 PDFs ficticios preparados em data\input."
Write-Host "Termos para teste: JASMIM AZUL e GIRASSOL DOURADO."
